/* ---------------- widgets ---------------- */
function onTheory(root){
 const w=root.querySelector('#w-globe');
 if(w){w.innerHTML=`<b>🌐 Глобус: поверни и нажми на любую точку</b>${SL('gL','Поворот:',-180,180,5,40)}${SL('gT','Наклон:',-60,60,5,30)}<div id="gP" class="fig" style="cursor:crosshair"></div><div id="gX" style="text-align:center;line-height:1.7;min-height:3em">Нажми на глобус — я покажу параллель и меридиан этой точки.</div>`;
  let pt=null;const g=id=>w.querySelector('#'+id);const R0=110;
  const u=()=>{const lon0=+g('gL').value,lat0=+g('gT').value;g('gLo').textContent=lon0+'°';g('gTo').textContent=lat0+'°';g('gP').innerHTML=globe({R:R0,lat0,lon0,step:30,pt,hlLat:pt?pt.lat:null,hlLon:pt?pt.lon:null});
   const svg=g('gP').querySelector('svg');svg.addEventListener('click',ev=>{const [x,y]=svgPt(svg,ev);const q=orthoInv(x-(R0+20),(R0+14)-y,lat0,lon0,R0);if(!q)return;pt={lat:Math.round(q.lat),lon:Math.round(q.lon)};u();
    g('gX').innerHTML=`Точка: <span class="out">${fmtLat(pt.lat)}, ${fmtLon(pt.lon)}</span><br><span class="small">Жёлтая линия — её параллель, синяя — меридиан. ${pt.lat>0?'Северное':'Южное'} и ${pt.lon>=0?'Восточное':'Западное'} полушария.</span>`;});};
  g('gL').oninput=u;g('gT').oninput=u;u();}
}

